scripts.莺儿对话.txt:
// 和莺儿对话

	If ($Event == 580) @Event580;
	If ($Event == 600) @Event600;
	If ($Event == 610) @Event610;
	
	Return;
	
@Event580:
	Say("莺儿：这里是帮主的寝宫，看什么看！再来东张西望的，小心打断你的狗腿。", 84);
	Say("独孤剑：好厉害的小丫头！", 2);
	Return;
	
@Event600:
	Say("莺儿：你是不是欺负我们帮主啦？她跑到湖边去了。", 84);
	Return;
	
@Event610:
	Say("莺儿：姑娘，如果这小子欺负你，你就告诉莺儿，我会好好教训他的！姑娘要多保重！呜呜……", 84);
	Return;

