scripts.封玉书死亡.txt:
//封玉书死亡

	Sleep(1200);
	FadeOut();
	Say("封玉书：这次算你们狠，咱们后会有期！", 64);
	ClearBody();
	DelNpc("封玉书");
	SaveNpc();
	SaveObj();
	StopMusic();
	PlayMusic("尘丝.mp3");
	SetNpcKind("杨瑛", 1);
	SetPlayerPos(5, 31);
	SetPlayerDir(7);
	SetNpcPos("杨瑛", 5, 29);
	SetNpcDir("杨瑛", 0);
	ClearEffect();
	FadeIn();
	
	Say("独孤剑：可惜让他跑了！", 5);
	PlayerGoto(5, 30);
	SetPlayerDir(5);
	SetNpcDir("杨瑛", 1);
	Say("独孤剑：帮主……", 1);
	Say("杨瑛：帮主的名号是在天王帮众面前叫的，你不是天王帮的人，不必叫我“帮主”……", 40);
	Sleep(500);
	Say("独孤剑：杨……姑娘，原来，一直暗中帮助我的人是你……", 4);
	Say("杨瑛：独孤大哥，我可以这样叫你吗？……", 40);
	Say("杨瑛：碧霞岛上的局是我安排的，目的是为了得到“山河社稷图”，整个事情都在我的计划之中，但是我却没有预料到会遇上你……", 40);
	Say("独孤剑：杨姑娘……", 1);
	Say("杨瑛：自从碧霞岛一别后，杨瑛，就已经不再是以前的杨瑛了。", 41);
	Say("独孤剑：杨姑娘，我……", 4);
	Say("杨瑛：记得小时候，父王常带我看湖，从那时起我就明白了一件事，这烟云浩荡的洞庭湖将是我一生的归宿。", 39);
	Say("杨瑛：独孤大哥，我明白，你和那位张姑娘情投意合，我……是不会让你为难的。", 41);
	Say("独孤剑：杨姑娘，对不起……", 4);
	Say("杨瑛：上天真是爱捉弄人！我平生最恨的人，偏偏是一个人人爱戴敬重的大英雄。", 41);
	Say("杨瑛：我最……的人，偏偏又已经情有所属……", 41);
	Say("独孤剑：杨姑娘，你一定会遇上一个比我好千百倍的人……", 1);
	Say("杨瑛：……独孤大哥，谢谢你。", 39);
	Sleep(500);

	AddNpc("npc025_杨湖.ini", 10, 42, 3);
	AddNpc("npc083_路云远.ini", 9, 43, 3);	
	NpcGotoEx("杨湖", 7, 36);
	NpcGotoEx("路云远", 6, 37);
	NpcGoto("杨湖", 5, 31);
	NpcGoto("路云远", 5, 32);
	SetNpcDir("杨湖", 4);
	SetNpcDir("路云远", 4);
	SetNpcDir("杨瑛", 0);
	SetPlayerDir(0);
	
	Say("封玉书：帮主，原来那奸细竟是封左使！", 100);
	Say("杨瑛：我都知道了，他是五色教的奸细，已经偷走了“山河社稷图”。", 39);
	Say("封玉书：啊？！想不到五色教已经渗入我天王帮的内部。", 100);
	Say("杨瑛：那封玉书偷了“山河社稷图”，此事关系重大，如不及时抓住他，不仅天王帮，恐怕整个武林，乃至整个中原都会有灭顶之灾。既然图是从天王帮丢的，我就有责任找回它，事不宜迟，我此刻就要出岛，杨左使你负责尽快部署！", 39);
	Say("杨湖：属下遵命！", 100);
	Say("杨瑛：路护法，帮中的事务就暂时有您老主持！", 39);
	Say("路云远：帮主放心，老夫自当尽心竭力。");
	Say("独孤剑：杨姑娘果然是一个有担待的人，我独孤剑也不能看着“山河社稷图”落入敌人之手而置之不理，我与你一同去，张氏兄妹就等在岛外，也可以做帮手。", 2);
	Say("杨瑛：那……也好，我们走吧。", 39);
	SetNpcKind("杨瑛", 3);
	SetNpcRelation("杨瑛", 2);
	SetNpcScript("杨瑛", "杨瑛的同伴对话.txt");
	SetNpcScript("杨湖", "杨湖对话.txt");
	SetNpcScript("路云远", "路云远对话.txt");
	Assign($Event, 610);
	SetMapTrap(1, "trap01.txt");
	Memo("封玉书原来竟是五色教的内奸。当夜，杨瑛向独孤剑倾诉衷肠，决定和独孤剑一起出岛追回“山河社稷图”。");
	Return;

