traps.trap02.txt:
// 与封玉书的战斗

	If ($Event == 605) @Event605;
	Return;
	
@Event605:
	SetNpcKind("杨瑛", 1);
	PlayerGoto(6, 37);
	NpcGoto("杨瑛", 7, 36);
	NpcGotoEx("杨瑛", 5, 31);
	PlayerGoto(5, 30);
	Sleep(100);
	SetNpcDir("杨瑛", 5);
	SetPlayerDir(5);
	Say("杨瑛：封左使，你在这干什么？", 42);
	SetNpcDir("封玉书", 1);
	Say("杨瑛：你手里拿的是——“山河社稷图”？！", 42);
	Say("封玉书：既然被你们发觉了，哼……", 64);
	Say("杨瑛：想不到你竟然做出这种叛逆的事！", 43);
	Say("封玉书：哼！在天王帮里要我听你一个小丫头的差遣，我真是不甘心！我投靠了五色教，得到重用，现在已经升任教中青剑堂的堂主，哈哈哈哈！", 64);
	Say("杨瑛：你这种叛教叛国的无耻之徒！", 43);
	Say("封玉书：杨姑娘，俗语说得好，识时务者为俊杰，大金国迟早有一天会占领中原的，我们又何苦做无谓的挣扎？我劝你不如和我一起投靠五色教和大金国，我会顾念旧情，让你在我手下作一个香主的，如何？", 64);
	Say("杨瑛：住口！平日里你道貌岸然，我还一直以为你是个为帮众着想的忠厚之人；不想，你却是个暗藏私心的小人！", 43);
	Say("封玉书：哼！不错，我是暗藏私心。难道帮主你不是吗？", 64);
	Say("封玉书：别以为我不知道。你为这小子放走张风之女，差点坏了本帮的大事……", 64);
	Say("独孤剑：……", 6);
	Say("封玉书：你不顾帮主的身份，暗地跑到华山，装什么采花大盗……", 64);
	Say("杨瑛：……", 40);
	Say("封玉书：你为了救这小子，不惜暗派古医仙远赴朱仙镇，还动用了本帮的圣药……难道帮主你做这些，都是为了天王帮千秋大计？帮主难道不是被这小子鬼迷了心窍……", 64);
	Say("杨瑛：你！原来你早就包藏祸心，一直监视我的行踪！", 43);
	Say("封玉书：哼哼！现在你什么都知道了，可惜一切都晚了，哈哈哈哈！地图我已拿到手，不再有什么顾忌，既已破脸，何必多言？去死吧！", 64);
	StopMusic();
	PlayMusic("沙场.mp3");
	SetNpcKind("杨瑛", 3);
	SetNpcRelation("封玉书",1);
	SetNpcDeathScript("封玉书", "封玉书死亡.txt");
	SetNpcDeathScript("独孤剑", "主角死亡.txt");
	SetNpcDeathScript("杨瑛", "主角死亡.txt");
	SetPlayerState(1);
    EnableFight();
	EnableNpcAI();
	SetNpcScript("杨瑛", "");
	SetMapTrap(1, "trap01.txt");
	SetMapTrap(2, "");
	Return;
